import React, { useState } from "react";
import { QueryClient, QueryClientProvider } from "react-query";

const withQueryClientProvider = <T extends {}>(
	WrappedComponent: React.ComponentType<T>
) => {
	const Component = (props: T) => {
		// Create once per mount; a new instance on every render would drop the query cache on re-render.
		const [queryClient] = useState(() => new QueryClient());

		return (
			<QueryClientProvider client={queryClient}>
				<WrappedComponent {...props} />
			</QueryClientProvider>
		);
	};
	Component.displayName = `withQueryClientProvider`;
	return Component;
};

export default withQueryClientProvider;
