import { useDeviceType } from "@blocks/hooks";
import { cn, getResponsiveHideClass } from "@blocks/utils";
import React from "react";

/**
 * Applies a greyed-out overlay class to a block's list-item wrapper when the
 * block is hidden on the device currently selected in the editor's preview
 * toggle, mirroring how the frontend hides it per breakpoint. Hooked into
 * `editor.BlockListBlock` so every block gets this for free without each
 * block's own Edit component needing to know about device preview state.
 */
const withResponsiveHidePreview = <
	T extends { attributes?: any; className?: string }
>(
	BlockListBlock: React.ComponentType<T>
) => {
	const Component = (props: T) => {
		const { deviceType } = useDeviceType();
		const hideClass = getResponsiveHideClass(
			deviceType,
			props.attributes ?? {}
		);

		return (
			<BlockListBlock
				{...props}
				className={cn(props.className, hideClass)}
			/>
		);
	};
	Component.displayName = `withResponsiveHidePreview`;
	return Component;
};

export default withResponsiveHidePreview;
