import { useBlockProps } from "@wordpress/block-editor";
import { Button, Flex, FlexItem, Placeholder } from "@wordpress/components";
import { useSelect } from "@wordpress/data";
import { dateI18n } from "@wordpress/date";
import { Fragment, useMemo } from "@wordpress/element";
import { decodeEntities } from "@wordpress/html-entities";
import { EditProps } from "blocks/types";
import classnames from "classnames";
import React from "react";

import { useBlockStyle } from "../../hooks";

import { useClientId, useCopyPasteStyles, useDeviceType } from "@blocks/hooks";

import {
	cn,
	EMPTY_ARRAY,
	getPostExcerptWords,
	getWPDateSettings,
} from "@blocks/utils";
import { upperFirst } from "lodash";
import { Icon } from "../../components";
import "../assets/sass/blocks/post-list/style.scss";
import InspectorControls from "./components/InspectorControls";

const Edit: React.ComponentType<EditProps<any>> = (props) => {
	const {
		className,
		attributes: {
			layout,
			layout1AdvancedStyle,
			layout2AdvancedStyle,
			label,
			column,
			category,
			tag,
			offset,
			orderBy,
			orderType,
			authorName,
			excludedCategory,
			postType,
			postCount,
			cssID,
			enableHeading,
			headingLayout,
			headingLayout1AdvancedStyle,
			headingLayout2AdvancedStyle,
			headingLayout3AdvancedStyle,
			headingLayout4AdvancedStyle,
			headingLayout5AdvancedStyle,
			headingLayout6AdvancedStyle,
			headingLayout7AdvancedStyle,
			headingLayout8AdvancedStyle,
			headingLayout9AdvancedStyle,

			imageToggle,
			position,
			size,
			hoverAnimation,

			enableDate,
			enableReadTime,
			enableViewCount,
			metaPosition,
			separatorType,
			enableIcon,

			excerptLimit,
			enableExcerpt,

			enableReadMore,
			readMoreText,

			enableViewMore,
			viewMoreText,
			enableViewMoreIcon,
			viewMoreIcon,
			viewMoreLink,
			viewButtonPosition,

			enablePagination,

			enableNumberList,
			numberLayout,
			numberPosition,
			enablePostsSeparator,

			hideOnDesktop,
			enableCategory,
			enableComment,
			categoryPosition,
			enableCategoryBorder,
			page,
		},
		setAttributes,
	} = props;

	const { clientId } = useClientId(props);
	const { deviceType } = useDeviceType();
	const { CopyPasterStyleBlockControl } = useCopyPasteStyles();
	const { Style } = useBlockStyle({
		blockName: "post-list",
		clientId,
		attributes: props.attributes,
		deviceType,
	});

	// @ts-ignore
	const authors = useSelect((select) => {
		const { getUsers } = select("core") as any;
		return getUsers({ per_page: -1 });
	}) as any[];

	const authorOptions = authors
		? authors.map((author) => ({
				value: author?.id.toString(),
				label: author?.name,
		  }))
		: [];

	const postTypeOptions = useSelect((select) => {
		const { getPostTypes } = select("core") as any;
		const { getCurrentPostType, getCurrentPostId } = select(
			"core/editor"
		) as any;

		const allPostTypes = getPostTypes({ per_page: -1 }) || [];
		const post = (select("core") as any).getEditedEntityRecord(
			"postType",
			getCurrentPostType(),
			getCurrentPostId()
		);
		const currentPostType = post?.type;
		const meta = post?.meta?._mzb_template;

		if (currentPostType === "mzb-builder-template") {
			return allPostTypes
				.filter((type: any) =>
					["post", "mzb-builder"].includes(type.slug)
				)
				.map((type: any) => {
					if (type.slug === "mzb-builder" && meta) {
						return {
							value: type.slug,
							label: `${upperFirst(meta)} Builder`,
						};
					}
					return {
						value: type.slug,
						label: type.name || type.slug,
					};
				});
		}

		return allPostTypes
			.filter((type: any) => type.slug !== "mzb-builder-template")
			.map((type: any) => ({
				value: type.slug,
				label: type.name || type.slug,
			}));
	}, []);

	const { posts, numberOfPosts, categories, tags } = useSelect(
		(select) => {
			const { getEntityRecords, getEditedEntityRecord } = select(
				"core"
			) as any;
			const { getCurrentPostType, getCurrentPostId } = select(
				"core/editor"
			) as any;

			const currentPost = getEditedEntityRecord(
				"postType",
				getCurrentPostType(),
				getCurrentPostId()
			);
			const isTemplate = currentPost?.type === "mzb-builder-template";
			const isArchive = currentPost?.type === "archive";
			const isSearch = currentPost?.type === "search";

			const selectedPostType = isTemplate ? "post" : postType || "post";

			const shouldSkipFilters = isTemplate && (isArchive || isSearch);

			const query: any = {
				per_page: postCount,
				offset: offset || 0,
				orderby: orderBy,
				order: orderType,
				author: authorName === "all" ? undefined : authorName,
			};

			if (!shouldSkipFilters) {
				if (category && category !== "all") {
					query.categories = parseInt(category);
				}
				if (tag && tag !== "all") {
					query.tags = tag;
				}
				if (excludedCategory && excludedCategory !== "") {
					query.categories_exclude = excludedCategory;
				}
			}

			return {
				posts:
					getEntityRecords("postType", selectedPostType, query) ??
					EMPTY_ARRAY,
				numberOfPosts:
					getEntityRecords("postType", selectedPostType, {
						per_page: -1,
						categories:
							"all" === category || selectedPostType !== "post"
								? undefined
								: parseInt(category),
					})?.length || 0,
				categories:
					getEntityRecords("taxonomy", "category", {
						per_page: -1,
					}) ?? EMPTY_ARRAY,
				tags:
					getEntityRecords("taxonomy", "post_tag", {
						per_page: -1,
					}) ?? EMPTY_ARRAY,
			};
		},
		[
			category,
			tag,
			postCount,
			offset,
			orderBy,
			orderType,
			authorName,
			excludedCategory,
			postType,
		]
	);

	const currentCategoryIndex = useMemo(() => {
		return categories
			? categories.findIndex((cat: any) => cat.id === parseInt(category))
			: -1; // Use -1 or another appropriate default value
	}, [category, categories]);

	const classNames = classnames(
		`mzb-post-list mzb-post-list-${clientId}`,
		size && `is-${size}`,
		className,
		hideOnDesktop && "magazine-blocks-hide-on-desktop"
	);

	const blockProps = useBlockProps({ className: classNames });

	const classNames2 = classnames(
		`mzb-posts mzb-${layout}`,
		enableNumberList && "mzb-number-list",
		numberLayout && `mzb-number-list__${numberLayout}`,
		numberPosition && `mzb-number-list__${numberPosition}`,
		{
			[`mzb-${layout1AdvancedStyle}`]: layout === `layout-1`,
			[`mzb-${layout2AdvancedStyle}`]: layout === `layout-2`,
		},
		layout1AdvancedStyle === "layout-1-style-2" &&
			`mzb-post-col--${column || 4}`
	);

	const classNames3 = classnames(`mzb-post-heading mzb-${headingLayout}`, {
		[`mzb-${headingLayout1AdvancedStyle}`]:
			headingLayout === `heading-layout-1`,
		[`mzb-${headingLayout2AdvancedStyle}`]:
			headingLayout === `heading-layout-2`,
		[`mzb-${headingLayout3AdvancedStyle}`]:
			headingLayout === `heading-layout-3`,
		[`mzb-${headingLayout4AdvancedStyle}`]:
			headingLayout === `heading-layout-4`,
		[`mzb-${headingLayout5AdvancedStyle}`]:
			headingLayout === `heading-layout-5`,
		[`mzb-${headingLayout6AdvancedStyle}`]:
			headingLayout === `heading-layout-6`,
		[`mzb-${headingLayout7AdvancedStyle}`]:
			headingLayout === `heading-layout-7`,
		[`mzb-${headingLayout8AdvancedStyle}`]:
			headingLayout === `heading-layout-8`,
		[`mzb-${headingLayout9AdvancedStyle}`]:
			headingLayout === `heading-layout-9`,
	});

	const NumberedPagination = ({
		totalPages,
		currentPage,
		onPageChange,
	}: {
		totalPages: number;
		currentPage: number;
		onPageChange: (val: number) => void;
	}) => {
		if (totalPages < 2) {
			return null; // Don't render pagination if there's only one page
		}

		const pages = Array.from(
			{ length: totalPages },
			(_, index) => index + 1
		);

		return (
			<Flex>
				{pages.map((page) => (
					<FlexItem key={page}>
						<Button
							variant={
								page === currentPage ? "primary" : undefined
							}
							onClick={() => onPageChange(page)}
						>
							{page}
						</Button>
					</FlexItem>
				))}
			</Flex>
		);
	};

	// Fetch the next page of posts
	const loadMorePosts = (nextPage: number) => {
		// Update the block's attributes to trigger a re-render with the next page
		setAttributes({ page: nextPage });
	};

	// Render numbered pagination
	const pagination = (
		<NumberedPagination
			totalPages={Math.ceil(numberOfPosts / postCount)}
			currentPage={page}
			onPageChange={loadMorePosts}
		/>
	);

	if (posts !== undefined && posts.length === 0) {
		return (
			<Fragment>
				<InspectorControls
					attributes={props.attributes}
					setAttributes={setAttributes}
					categories={categories}
					tags={tags}
					authorOptions={authorOptions}
					postTypeOptions={postTypeOptions}
				/>
				<CopyPasterStyleBlockControl withBlockControls />
				<Style />
				<div {...blockProps} id={cssID}>
					<Placeholder
						icon={
							<Icon type="blockIcon" name="postList" size={24} />
						}
						label="Post List"
						instructions="No posts found. Please publish posts to display them in this block."
					/>
				</div>
			</Fragment>
		);
	}

	return (
		<Fragment>
			<InspectorControls
				attributes={props.attributes}
				setAttributes={setAttributes}
				categories={categories}
				tags={tags}
				authorOptions={authorOptions}
				postTypeOptions={postTypeOptions}
			/>
			<CopyPasterStyleBlockControl withBlockControls />
			<Style />
			<div {...blockProps} id={cssID}>
				{enableHeading && (
					<div className={classNames3}>
						{enableHeading === true && (
							<h2 className="mzb-heading-text">{label}</h2>
						)}
						{viewButtonPosition === "top" && enableViewMore && (
							<div className="mzb-view-more">
								{/*eslint-disable-next-line react/jsx-no-target-blank */}
								<a
									href={"#"}
									target={
										viewMoreLink?.newTab
											? "_blank"
											: "_self"
									}
									rel={[
										viewMoreLink?.newTab
											? "noreferrer noopener"
											: "",
										viewMoreLink?.noFollow
											? "nofollow"
											: "",
									]
										.filter(Boolean)
										.join(" ")}
								>
									<p>{viewMoreText}</p>
									{enableViewMoreIcon && (
										<Icon
											type="frontendIcon"
											name={viewMoreIcon}
											size={24}
										/>
									)}
								</a>
							</div>
						)}
					</div>
				)}
				{
					<div className={classNames2}>
						<Fragment>
							{(posts || []).map((post: any, idx: number) => {
								const maxWords = excerptLimit;
								const excerpt = getPostExcerptWords(
									post,
									maxWords
								);

								return (
									<div
										className={cn(
											"mzb-post",
											`magazine-post--pos-${
												position || "left"
											}`,
											enablePostsSeparator &&
												`mzb-post-separator`
										)}
										key={idx}
									>
										{position === "left" &&
											post
												?.magazine_blocks_featured_image_url
												?.full?.[0] &&
											imageToggle && (
												<div
													className={`mzb-featured-image ${hoverAnimation} mzb-category-${categoryPosition}`}
												>
													<img
														src={
															post
																?.magazine_blocks_featured_image_url
																?.full[0]
														}
													/>
													{(enableCategory ||
														enableComment) &&
														categoryPosition ===
															"in-image" && (
															<div
																className={
																	"mzb-post-meta" +
																	(enableCategoryBorder
																		? " mzb-post-border-enable"
																		: "")
																}
															>
																{enableCategory && (
																	<span
																		className="mzb-post-categories"
																		dangerouslySetInnerHTML={{
																			__html: post.magazine_blocks_category,
																		}}
																	/>
																)}
																{enableComment && (
																	<span className="comments-link">
																		<Icon
																			type="frontendIcon"
																			name="commentIcon"
																			size={
																				24
																			}
																		/>{" "}
																		{
																			post.magazine_blocks_comment
																		}
																	</span>
																)}
															</div>
														)}
												</div>
											)}
										<div className="mzb-post-content">
											{metaPosition === "top" && (
												<>
													{(enableDate ||
														enableReadTime ||
														enableViewCount) && (
														<div
															className={cn(
																"mzb-post-entry-meta",
																separatorType &&
																	`mzb-meta-separator--${separatorType}`
															)}
														>
															{enableDate && (
																<span className="mzb-post-date">
																	{enableIcon ===
																		true && (
																		<Icon
																			type="blockIcon"
																			name="calendar"
																			size={
																				24
																			}
																		/>
																	)}
																	<a href="#">
																		{" "}
																		{dateI18n(
																			getWPDateSettings()
																				.formats
																				.date,
																			post?.date_gmt,
																			undefined
																		)}{" "}
																	</a>
																</span>
															)}

															{enableReadTime ===
																true && (
																<span className="mzb-post-read-time">
																	{enableIcon ===
																		true && (
																		<Icon name="clock" />
																	)}
																	<span>
																		{
																			post?.magazineBlocksPostReadTime
																		}{" "}
																		min read
																	</span>
																</span>
															)}
															{enableViewCount ===
																true && (
																<span className="mzb-post-view-count">
																	{enableIcon ===
																		true && (
																		<Icon
																			name="eyeO"
																			fill="#fff"
																		/>
																	)}
																	<span>
																		{post?.magazineBlocksPostViewCount ||
																			0}{" "}
																		views
																	</span>
																</span>
															)}
														</div>
													)}

													{(enableCategory ||
														enableComment) &&
														categoryPosition ===
															"out-image" && (
															<div
																className={
																	"mzb-post-meta" +
																	(enableCategoryBorder
																		? " mzb-post-border-enable"
																		: "")
																}
															>
																{enableCategory && (
																	<span
																		className="mzb-post-categories"
																		dangerouslySetInnerHTML={{
																			__html: post.magazine_blocks_category,
																		}}
																	/>
																)}
																{enableComment && (
																	<span className="comments-link">
																		<Icon
																			type="frontendIcon"
																			name="commentIcon"
																			size={
																				24
																			}
																		/>{" "}
																		{
																			post.magazine_blocks_comment
																		}
																	</span>
																)}
															</div>
														)}

													<h3 className="mzb-post-title">
														<a href={"#"}>
															{decodeEntities(
																post?.title
																	?.rendered ||
																	"(Untitled)"
															)}
														</a>
													</h3>
												</>
											)}

											{metaPosition === "bottom" && (
												<>
													{(enableCategory ||
														enableComment) &&
														categoryPosition ===
															"out-image" && (
															<div
																className={
																	"mzb-post-meta" +
																	(enableCategoryBorder
																		? " mzb-post-border-enable"
																		: "")
																}
															>
																{enableCategory && (
																	<span
																		className="mzb-post-categories"
																		dangerouslySetInnerHTML={{
																			__html: post.magazine_blocks_category,
																		}}
																	/>
																)}
																{enableComment && (
																	<span className="comments-link">
																		<Icon
																			type="frontendIcon"
																			name="commentIcon"
																			size={
																				24
																			}
																		/>{" "}
																		{
																			post.magazine_blocks_comment
																		}
																	</span>
																)}
															</div>
														)}
													<h3 className="mzb-post-title">
														<a href={"#"}>
															{decodeEntities(
																post?.title
																	?.rendered ||
																	"(Untitled)"
															)}
														</a>
													</h3>

													{(enableDate ||
														enableReadTime ||
														enableViewCount) && (
														<div
															className={cn(
																"mzb-post-entry-meta",
																separatorType &&
																	`mzb-meta-separator--${separatorType}`
															)}
														>
															{enableDate && (
																<span className="mzb-post-date">
																	{enableIcon ===
																		true && (
																		<Icon
																			type="blockIcon"
																			name="calendar"
																			size={
																				24
																			}
																		/>
																	)}
																	<a href="#">
																		{" "}
																		{dateI18n(
																			getWPDateSettings()
																				.formats
																				.date,
																			post?.date_gmt,
																			undefined
																		)}{" "}
																	</a>
																</span>
															)}
															{enableReadTime && (
																<span className="mzb-post-read-time">
																	{enableIcon ===
																		true && (
																		<Icon name="clock" />
																	)}
																	<span>
																		{
																			post?.magazineBlocksPostReadTime
																		}{" "}
																		min read
																	</span>
																</span>
															)}
															{enableViewCount && (
																<span className="mzb-post-view-count">
																	{enableIcon ===
																		true && (
																		<Icon
																			name="eyeO"
																			fill="#fff"
																		/>
																	)}
																	<span>
																		{post?.magazineBlocksPostViewCount ||
																			0}{" "}
																		views
																	</span>
																</span>
															)}
														</div>
													)}
												</>
											)}

											{(enableExcerpt ||
												enableReadMore) && (
												<div className="mzb-entry-content">
													{enableExcerpt && (
														<div
															className="mzb-entry-summary"
															dangerouslySetInnerHTML={{
																__html: excerpt,
															}}
														/>
													)}
													{enableReadMore && (
														<div className="mzb-read-more">
															<a href={"#"}>
																{readMoreText}
															</a>
														</div>
													)}
												</div>
											)}
										</div>
										{position === "right" &&
											post
												?.magazine_blocks_featured_image_url
												?.full?.[0] &&
											imageToggle && (
												<div
													className={`mzb-featured-image ${hoverAnimation}`}
												>
													<img
														src={
															post
																?.magazine_blocks_featured_image_url
																?.full[0]
														}
													/>
												</div>
											)}
									</div>
								);
							})}
							{enablePagination && (
								<div className="mzb-pagination-numbers">
									{pagination}
								</div>
							)}
						</Fragment>
					</div>
				}
				{viewButtonPosition === "bottom" && enableViewMore && (
					<div className="mzb-view-more">
						{/*eslint-disable-next-line react/jsx-no-target-blank */}
						<a
							href={"#"}
							target={viewMoreLink?.newTab ? "_blank" : "_self"}
							rel={[
								viewMoreLink?.newTab
									? "noreferrer noopener"
									: "",
								viewMoreLink?.noFollow ? "nofollow" : "",
							]
								.filter(Boolean)
								.join(" ")}
						>
							<p>{viewMoreText}</p>
							{enableViewMoreIcon && (
								<Icon
									type="frontendIcon"
									name={viewMoreIcon}
									size={24}
								/>
							)}
						</a>
					</div>
				)}
			</div>
		</Fragment>
	);
};

export default Edit;
